  RelicConfig_129304_BattleDesc = {
    Text = "<OrangeQuality:ทองคำการประสาน>：「การประสานอริธเมทิกา」จะเพิ่มพลังการคำนวณสูงสุด 1 หน่วย สำหรับทุก 1% ของความแรงดาเมจจะทำให้ความรู้ทางจิตวิญญาณเชิงลึกเพิ่มขึ้น 1%\n<OrangeQuality:ของขวัญแห่งมิติ>：เริ่มต้นการสำรวจ จะได้รับสิ่งประดิษฐ์ภาพมิติแบบสุ่ม 1 ชิ้น ขีดจำกัดไพ่บนมือเพิ่มขึ้น 2\n<OrangeQuality:พิธีแห่งการได้รับพร>：รางวัลจากการเอาชนะผู้นำในระยะที่ 1 และ 2 จะเปลี่ยนเป็นสิ่งประดิษฐ์ที่ได้รับพรแบบสุ่ม 3 ชิ้นเลือก 1\n<RedQuality:ความอ่อนล้าจากการเดินทางไกล>：ผลการฟื้นฟูชีวิตทั้งหมดในระหว่างการต่อสู้ลดลง 50% เมื่อเลือก「การฝัง」จาก「กระดูกซีดจาง」จะเปลี่ยนเป็นฟื้นฟู 25% ของพลังชีวิตสูงสุด\n<RedQuality:สัญญาณแห่งการสตั้น>：เมื่อเริ่มต่อสู้ ทุกผู้ปลุกตื่นจะมีความอาลีมัสและพลังงานกุญแจเงินลดลง 50%\n<RedQuality:ทางเดินนิรันดร์แห่งราตรี>：เมื่อเริ่มต้นการสำรวจ พื้นฐานความอาลีมัสและพลังงานกุญแจเงินของผู้ปลุกตื่นทั้งหมดจะเพิ่มขึ้น 50%"
  },
  RelicConfig_129304_Desc = {
    Text = "<OrangeQuality:ทองคำการประสาน>：「การประสานอริธเมทิกา」จะเพิ่มพลังการคำนวณสูงสุด 1 หน่วย สำหรับทุก 1% ของความแรงดาเมจจะทำให้ความรู้ทางจิตวิญญาณเชิงลึกเพิ่มขึ้น 1%\n<OrangeQuality:ของขวัญแห่งมิติ>：เริ่มต้นการสำรวจ จะได้รับสิ่งประดิษฐ์ภาพมิติแบบสุ่ม 1 ชิ้น ขีดจำกัดไพ่บนมือเพิ่มขึ้น 2\n<OrangeQuality:พิธีแห่งการได้รับพร>：รางวัลจากการเอาชนะผู้นำในระยะที่ 1 และ 2 จะเปลี่ยนเป็นสิ่งประดิษฐ์ที่ได้รับพรแบบสุ่ม 3 ชิ้นเลือก 1\n<RedQuality:ความอ่อนล้าจากการเดินทางไกล>：ผลการฟื้นฟูชีวิตทั้งหมดในระหว่างการต่อสู้ลดลง 50% เมื่อเลือก「การฝัง」จาก「กระดูกซีดจาง」จะเปลี่ยนเป็นฟื้นฟู 25% ของพลังชีวิตสูงสุด\n<RedQuality:สัญญาณแห่งการสตั้น>：เมื่อเริ่มต่อสู้ ทุกผู้ปลุกตื่นจะมีความอาลีมัสและพลังงานกุญแจเงินลดลง 50%\n<RedQuality:ทางเดินนิรันดร์แห่งราตรี>：เมื่อเริ่มต้นการสำรวจ พื้นฐานความอาลีมัสและพลังงานกุญแจเงินของผู้ปลุกตื่นทั้งหมดจะเพิ่มขึ้น 50%"
