  },
  RelicConfig_50489_BattleDesc = {
    Text = "อัตราการโจมตีคริติคอลและความเสียหายวิกฤตเพิ่มขึ้น 100%。ทุกครั้งที่ทำดาเมจ 1 ครั้ง อัตราการโจมตีคริติคอลและความเสียหายวิกฤตของผู้ปลุกตื่นทั้งหมดจะลดลง 10% โดยลดได้สูงสุดถึง 50%。ทุกครั้งที่ทำดาเมจ 1 ครั้ง พิษและการโต้กลับในรอบนี้จะเพิ่มขึ้น 10% โดยเพิ่มได้สูงสุดถึง 50%。"
  },
  RelicConfig_50489_Desc = {
    Text = "อัตราการโจมตีคริติคอลและความเสียหายจากการโจมตีคริติคอลเพิ่มขึ้น 100%。เมื่อทำความเสียหาย 1 ครั้ง/ความเสียหายจากหนวดสัมผัส ในรอบนี้：ผู้ปลุกตื่นทั้งหมดจะลดความเสียหายวิกฤตลง 10%，สูงสุดลดได้ 50%。พิษและการโต้กลับที่เกิดขึ้นเพิ่มขึ้น 10%，สูงสุดเพิ่มได้ 50%。"
  },
  RelicConfig_50489_Name = {
    Text = "<OrangeQuality:ลูกตุ้มเวลา「ย้ายถ่าย」>"
  },
  RelicConfig_51686_BattleDesc = {
    Text = "ทุกครั้งที่เล่นการ์ดคำสั่งที่มีร่างกายที่ตื่นขึ้นแตกต่างจากการ์ดก่อนหน้า ร่างกายที่ตื่นขึ้นนั้นจะได้รับอาลีมัส 3 หน่วย และสะสม 1 ชั้น「กำลังวังชา」。เมื่อสะสมครบ 10 ชั้น จะทำให้ล้าง「กำลังวังชา」ทั้งหมด และใส่การ์ดคำสั่งแบบสุ่มที่มี「ใช้」ลดการใช้พลังการคำนวณของร่างกายที่ตื่นขึ้นแต่ละตัวลง 1 หน่วยลงในมือ โดยสามารถใช้ได้สูงสุด 1 ครั้งต่อเทิร์น。"
  },
  RelicConfig_51686_Desc = {
    Text = "ทุกครั้งที่เล่นการ์ดคำสั่งที่มีร่างกายที่ตื่นขึ้นแตกต่างจากการ์ดก่อนหน้า ร่างกายที่ตื่นขึ้นนั้นจะได้รับอาลีมัส 3 หน่วย และสะสม 1 ชั้น「กำลังวังชา」 เมื่อสะสมครบ 10 ชั้น จะทำการล้าง「กำลังวังชา」ทั้งหมด และนำการ์ดคำสั่งแบบสุ่มที่มี「ใช้」และลดการใช้พลังการคำนวณของร่างกายที่ตื่นขึ้นทั้งหมด 1 ใบไปใส่ในมือ โดยสามารถใช้ได้สูงสุด 1 ครั้งต่อเทิร์น。"
