  RelicConfig_57667_BattleDesc = {
    Text = "เริ่มต้นด้วย 2 ชั้นของพลังของแม่พระ หลังจากรอบที่สาม ในแต่ละรอบเริ่มต้นสามารถเลือกใช้พลังของแม่พระเพื่อรับผลลัพธ์ที่แตกต่างกันหรือฟื้นคืนพลังของแม่พระ หากได้รับความเสียหายที่ทำให้ตาย จะฟื้นคืนชีพและใช้พลังของแม่พระทั้งหมด ทุกชั้นจะฟื้นฟู 10% ของ HP ใช้ได้เพียง 1 ครั้งเท่านั้น。"
