  RelicConfig_58872_Desc = {
    Text = "เมื่อการต่อสู้เริ่มต้นขึ้น ขีดจำกัดอริธเมทิกา +1 และปลุกตื่นผู้ปลุกตื่นทั้งหมด ใน 5 รอบถัดไป ในแต่ละรอบเริ่มต้นจะได้รับเรลิกหนึ่งชิ้น ซึ่งมี「มีดผ่าตัดผุกร่อน, new-style wheel axle, บ้านของเรา, ตะขอพิศดาร, ลูกตุ้มเวลา·หลงใหล」。"
