  RelicConfig_59118_BattleDesc = {
    Text = "เมื่อเริ่มต้นรอบ จะได้รับการ์ด 1 ใบ「ลูกเต๋าโชคลาภของไรเกอร์」，ผลลัพธ์ที่ทอยลูกเต๋าจะเพิ่มขึ้น +1。เมื่อเริ่มต้นรอบและทุกครั้งที่ทอยลูกเต๋า ผู้ปลุกตื่นทั้งหมดจะได้รับความเสียหายจากการโจมตีคริติคอล 4% สูงสุด 100%。"
  },
  RelicConfig_59118_Desc = {
    Text = "เมื่อเริ่มต้นรอบ จะได้รับการ์ด「ลูกเต๋าโชคลาภของไรเกอร์」 1 ใบ และผลที่ออกจากลูกเต๋าจะเพิ่มขึ้น +1 ในช่วงเริ่มต้นรอบและหลังจากการทอยลูกเต๋าทุกครั้ง ผู้ปลุกตื่นทั้งหมดจะได้รับความเสียหายจากการโจมตีคริติคอล 4% โดยสูงสุดจะได้รับ 100%。"
  },
