  RelicConfig_60723_BattleDesc = {
    Text = "แต้มอริธเมทิกาเพิ่มขึ้น 1 เมื่อเริ่มต้นรอบจะจั่วการ์ดเพิ่ม 1 ใบ และจะได้รับการ์ด「ซิมโฟนีประสานเสียง」 หากเล่นการ์ดคำสั่งที่มีการใช้พลังการคำนวณเท่ากันติดต่อกัน 3 ครั้ง ร่างกายที่ปลุกตื่นทั้งหมดจะได้รับอาลีมัส 20 หน่วย และจะรีเซ็ตจำนวนครั้งเมื่อเริ่มต้นรอบและหลังจากที่กระตุ้นแล้ว。"
  },
  RelicConfig_60723_Desc = {
